  if (book_load("/app/inkurn/book.tsv") != 0) {
    return 2;
  }
  graph_build();
  op_pick();
  rk_wrap();

  for (i = 0; i < PN; i++) {
    ord[i] = PLAN[i];
  }
  if (PN > 1) {
    qsort(ord, (size_t)PN, sizeof ord[0], cmp_wire);
