#include "pick.h"
#include "store.h"

/* Select the smallest intern identity each time from the monitors that are
   currently releasable.  TID and input position make duplicate IDs stable. */
static int before(int a, int b) {
  if (G[a].tag != G[b].tag) return G[a].tag < G[b].tag;
  if (G[a].tid != G[b].tid) return G[a].tid < G[b].tid;
  return a < b;
}

int op_pick(void) {
  PN = 0;
  for (int i = 0; i < GN; i++) G[i].done = 0;

  for (;;) {
    int cur = -1;
    for (int i = 0; i < GN; i++) {
      if (!G[i].done && G[i].indeg == 0 &&
          (cur < 0 || before(i, cur))) cur = i;
    }
    if (cur < 0) break;
    PLAN[PN++] = cur;
    G[cur].done = 1;
    for (int k = 0; k < nsucc[cur]; k++) {
      int j = succ[cur][k];
      if (G[j].indeg > 0) G[j].indeg--;
    }
  }

  /* Deadlocked members are not topologically releasable.  Their identity
     order is nevertheless canonical and independent of dump tokens/order. */
  while (PN < GN) {
    int cur = -1;
    for (int i = 0; i < GN; i++) {
      if (!G[i].done && (cur < 0 || before(i, cur))) cur = i;
    }
    PLAN[PN++] = cur;
    G[cur].done = 1;
  }
  return 0;
}
EOF
