static void dir_of(const char *a, char *dir, size_t cap) {
  const char *slash = strrchr(a, '/');
  if (!slash) { snprintf(dir, cap, "."); return; }
  size_t n = (size_t)(slash - a);
  if (n >= cap) n = cap - 1;
  memcpy(dir, a, n);
  dir[n] = 0;
}

int n_bind(const char *a) {
  char dir[256], okp[320], tmp[512], oktmp[512];
  FILE *f;
  dir_of(a, dir, sizeof dir);
  snprintf(okp, sizeof okp, "%s/mill.ok", dir);
  snprintf(tmp, sizeof tmp, "%s.tmp.%ld", a, (long)getpid());
  snprintf(oktmp, sizeof oktmp, "%s.tmp.%ld", okp, (long)getpid());

  f = fopen(tmp, "w");
  if (!f) return 2;
  for (int i = 0; i < PN; i++) {
    if (fprintf(f, "%u\n", G[PLAN[i]].tag) < 0) {
      fclose(f); unlink(tmp); return 2;
